// Final Class: Locked against inheritance
public final class SecurityToken {
    private final String tokenPayload;
    private final long expirationEpoch;

    public SecurityToken(String payload, long expiration) {
        this.tokenPayload = payload;
        this.expirationEpoch = expiration;
    }

    public String getTokenPayload() { return tokenPayload; }
    public long getExpirationEpoch() { return expirationEpoch; }

    public boolean isExpired(long currentEpoch) {
        return currentEpoch > expirationEpoch;
    }
}

// Attempting inheritance below causes a compiler error:
// class RogueToken inherits from SecurityToken {} // COMPILE ERROR: cannot inherit from final SecurityToken

public class Main {
    public static void main(String[] args) {
        SecurityToken token = new SecurityToken("AUTH-XYZ-991", 1800000000L);
        System.out.println("Token: " + token.getTokenPayload());
        System.out.println("Is expired at 1700000000: " + token.isExpired(1700000000L));
    }
}

