class BankingCompliance {
    private String bankName;

    public BankingCompliance(String name) {
        this.bankName = name;
    }

    // Standard method: Subclasses can customize this if desired
    public void displayWelcome() {
        System.out.println("Welcome to " + bankName);
    }

    // FINAL METHOD: Subclasses are strictly FORBIDDEN from overriding this compliance formula!
    public final double calculateMandatoryTaxReserve(double annualProfit) {
        // Legally mandated 22% statutory reserve
        return annualProfit * 0.22;
    }
}

public class Main {
    public static void main(String[] args) {
        BankingCompliance comp = new BankingCompliance("Apex Commercial Bank");
        comp.displayWelcome();
        double reserve = comp.calculateMandatoryTaxReserve(1000000.0);
        System.out.println("Mandatory 22% Reserve on $1M: $" + reserve);
    }
}

