class PasswordHasher {
    public final String hashPassword(String raw) {
        if (raw == null) return "HASHED_EMPTY";
        return "HASHED_" + raw;
    }
}

public class Main {
    public static void main(String[] args) {
        PasswordHasher hasher = new PasswordHasher();
        System.out.println("Result: " + hasher.hashPassword("mypassword123"));
    }
}

final class ImmutableCoordinate {
    private final int x;
    private final int y;

    public ImmutableCoordinate(int x, int y) {
        this.x = x;
        this.y = y;
    }

